typedef unsigned long long u64;

extern "C" void pack_string(void *, const char *)
    __asm__("pack_string__7pstringPCc");
extern "C" void assign_string(void *, const void *)
    __asm__("__as__7stringxRC7stringx");

class pstring
{
public:
    u64 data[4];

    pstring(const char *text)
    {
        pack_string(this, text);
    }

    bool operator==(const pstring &other) const
    {
        for (unsigned i = 0; i < 4; ++i)
            if (data[i] != other.data[i])
                return false;
        return true;
    }
};

class stringx
{
public:
    void operator=(const stringx &other)
    {
        assign_string(this, &other);
    }
};

class script_data_interface
{
    void *vtable;
    void *owner;
    char numbers[32];
    stringx strings[4];

public:
    bool get_ifc_str(const pstring &attribute, stringx &value);
};

bool script_data_interface::get_ifc_str(
    const pstring &attribute,
    stringx &value)
{
    static pstring str1("SD_STR_1");
    if (attribute == str1)
    {
        value = strings[0];
        return true;
    }

    static pstring str2("SD_STR_2");
    if (attribute == str2)
    {
        value = strings[1];
        return true;
    }

    static pstring str3("SD_STR_3");
    if (attribute == str3)
    {
        value = strings[2];
        return true;
    }

    static pstring str4("SD_STR_4");
    if (attribute == str4)
    {
        value = strings[3];
        return true;
    }

    return false;
}
